mapper.select:
/* adpt.select_API_PARAM_list */ SELECT P.PARAM_NO ,P.API_NO ,P.PARAM_TYPE_CD ,COALESCE(B.CD_NM,'') AS PARAM_TYPE_CD_NM ,P.SORT_ODRG ,P.PARAM_NM ,P.DATA_TYPE_CD ,COALESCE(C.CD_NM,'') AS DATA_TYPE_CD_NM ,P.PARAM_DESC ,P.EXAM ,COALESCE(P.PRNTS_PARAM_NO, 0) AS PRNTS_PARAM_NO ,TO_CHAR(P.REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS REG_DT ,P.REGR ,TO_CHAR(P.AMD_DT, 'YYYY-MM-DD HH24:MI:SS') AS AMD_DT ,P.RES_CD ,P.RES_DESC ,P.PARAM_LOC ,P.OBJ_NO ,P.OBJ_ODRG ,P.REQUIRED ,P.PERSONAL_DATA ,P.DO_NOT_SEND ,P.FIXED_VALUE ,P.HIDDEN ,P.MAPPING_KEY ,P.HDP_URL_DECODE ,P.HDP_URL_ENCODE ,P.HDP_UPLOAD_TARGET ,P.BIGO FROM KOA_TB_API_PARAM P LEFT OUTER JOIN KOA_TB_COMN_CD B ON (B.COMN_CD = P.PARAM_TYPE_CD AND B.GROUP_CD = 'PRMTYP1000') LEFT OUTER JOIN KOA_TB_COMN_CD C ON (C.COMN_CD = P.DATA_TYPE_CD AND C.GROUP_CD = 'DATTYP1000') WHERE (P.API_NO = #{apiNo}) AND (P.PARAM_TYPE_CD IN ('PRMTYP1010', 'PRMTYP1020')) AND (P.DATA_TYPE_CD IN ('DATTYP1010','DATTYP1020','DATTYP1030','DATTYP1040','DATTYP1050','DATTYP1060'))
AND P.PARAM_LOC IN
#{item}
ORDER BY P.PARAM_TYPE_CD, P.PARAM_LOC, P.SORT_ODRG, P.PARAM_NO

/* adpt.select_API_PARAM_TEST_list */ ;WITH CTE_API_PARAM(LEVEL, PARAM_NM_FULL, PARAM_NO, API_NO, PARAM_TYPE_CD, SORT_ODRG, PARAM_NM, DATA_TYPE_CD, EXAM, PRNTS_PARAM_NO, PARAM_LOC, REQUIRED, DO_NOT_SEND, FIXED_VALUE, HIDDEN, PARAM_SANDBOX_YN) AS ( SELECT 0 ,CAST(P.PARAM_NM AS VARCHAR($n)) ,P.PARAM_NO ,P.API_NO ,P.PARAM_TYPE_CD ,P.SORT_ODRG ,P.PARAM_NM ,P.DATA_TYPE_CD ,P.EXAM ,COALESCE(P.PRNTS_PARAM_NO, 0) AS PRNTS_PARAM_NO ,P.PARAM_LOC ,P.REQUIRED ,P.DO_NOT_SEND ,P.FIXED_VALUE ,P.HIDDEN ,P.PARAM_SANDBOX_YN FROM KOA_TB_API_PARAM P WHERE (COALESCE(P.PRNTS_PARAM_NO, 0) = 0) AND (P.API_NO = #{apiNo}) UNION ALL SELECT CC.LEVEL + 1 ,CAST((CC.PARAM_NM_FULL || '.' || C.PARAM_NM) AS VARCHAR(500)) ,C.PARAM_NO ,C.API_NO ,C.PARAM_TYPE_CD ,C.SORT_ODRG ,C.PARAM_NM ,C.DATA_TYPE_CD ,C.EXAM ,COALESCE(C.PRNTS_PARAM_NO, 0) AS PRNTS_PARAM_NO ,C.PARAM_LOC ,C.REQUIRED ,C.DO_NOT_SEND ,C.FIXED_VALUE ,C.HIDDEN ,C.PARAM_SANDBOX_YN FROM KOA_TB_API_PARAM C INNER JOIN CTE_API_PARAM CC ON (CC.PARAM_NO = C.PRNTS_PARAM_NO) ) SELECT P.LEVEL , P.PARAM_NM_FULL , P.PARAM_NO , P.API_NO , P.PARAM_TYPE_CD , P.SORT_ODRG , P.PARAM_NM , COALESCE(B.CD_NM, '') AS DATA_TYPE_CD_NM , P.EXAM , P.PRNTS_PARAM_NO , P.PARAM_LOC , COALESCE(P.REQUIRED, 'N') AS REQUIRED , COALESCE(P.DO_NOT_SEND, 'N') AS DO_NOT_SEND , COALESCE(P.FIXED_VALUE, '') AS FIXED_VALUE , COALESCE(P.HIDDEN, 'N') AS HIDDEN , COALESCE(P.PARAM_SANDBOX_YN, 'N') AS PARAM_SANDBOX_YN FROM CTE_API_PARAM P LEFT OUTER JOIN KOA_TB_COMN_CD B ON (B.COMN_CD = P.DATA_TYPE_CD AND B.GROUP_CD = 'DATTYP1000') WHERE (1 = 1)
AND P.PARAM_TYPE_CD IN
#{item}
AND ( ((P.PARAM_LOC IN ('header', 'query')) AND (B.CD_NM IN ('Array','String','Number','Integer','Boolean'))) OR ((P.PARAM_LOC IN ('body')) AND (B.CD_NM IN ('Object','Array','String','Number','Integer','Boolean'))) ) AND (COALESCE(P.DO_NOT_SEND, 'N') != 'Y') AND (COALESCE(P.HIDDEN, 'N') != 'Y') ORDER BY P.PARAM_TYPE_CD, P.PARAM_LOC, P.SORT_ODRG, P.PARAM_NO

mapper.insert:
/* adpt.insert_API_TESTCASE */

    SELECT CURRVAL('koa_tb_api_testcase_testcase_id_seq')

INSERT INTO KOA_TB_API_TESTCASE (
     API_NO
    ,TESTCASE_NM
    ,PARAM_GUB
    ,PARAM_HEADER
    ,PARAM_BODY
    ,PARAM_QUERY
    ,PARAM_HEADER_JSON
    ,PARAM_BODY_JSON
    ,ASSERT_CASE
    ,ASSERT_FIELD
    ,ASSERT_OPERATOR
    ,ASSERT_VALUE
    ,INFOVIEW_YN
    ,DEL_YN
    ,REG_DT
    ,REGR
    ,AMD_DT
    ,AMDR
)
VALUES (
     #{api_no}
    ,#{testcase_nm}
    ,#{param_gub}
    ,#{param_header}
    ,#{param_body}
    ,#{param_query}
    ,#{param_header_json}
    ,#{param_body_json}
    ,#{assert_case}
    ,#{assert_field}
    ,#{assert_operator}
    ,#{assert_value}
    ,#{infoview_yn}
    ,'N'
    ,NOW()
    ,#{mbrId}
    ,NOW()
    ,#{mbrId}
)

mapper.update:
/* adpt.update_API_TESTCASE */
UPDATE KOA_TB_API_TESTCASE
SET TESTCASE_NM = #{testcase_nm}
  ,PARAM_GUB = #{param_gub}
  ,PARAM_HEADER = #{param_header}
  ,PARAM_BODY = #{param_body}
  ,PARAM_QUERY = #{param_query}
  ,PARAM_HEADER_JSON = #{param_header_json}
  ,PARAM_BODY_JSON = #{param_body_json}
  ,ASSERT_CASE = #{assert_case}
  ,ASSERT_FIELD = #{assert_field}
  ,ASSERT_OPERATOR = #{assert_operator}
  ,ASSERT_VALUE = #{assert_value}
  ,INFOVIEW_YN = #{infoview_yn}
  ,AMD_DT = NOW()
  ,AMDR = #{mbrId}
WHERE (TESTCASE_ID = #{testcase_id})

